        assert_eq!(result["pending"], json!([task.task_id]), "{result}");
        trace.assert_calm("TaskWait");
        drop(trace);
        assert_eq!(epoch.get(), seen);
        assert_eq!(active.load(Ordering::Acquire), 0);
        assert_eq!(
            serde_json::to_value(
                shared
                    .lock()
                    .unwrap()
                    .delegation_store
                    .get(&task.task_id)
                    .unwrap()
                    .unwrap()
            )
            .unwrap(),
            before
        );
