    #[test]
    fn spec172_remote_rate_limit_binds_only_current_managed_child_and_exact_definition() {
        use bridget_transport::protocol::RateLimitSource;
        let (mut st, config, mut task, _result) = remote162_capture_fixture();
        let root = st.fixture_root.as_ref().unwrap().0.clone();
        let value = json!({"agents":{"native-test":{"command":"/bin/sh","args":["app-server"],
            "protocol":"codex_app_server","forbidden_env":[],"capabilities":{"execution_paths":["codex_app_server"],
                "models":{"custom/model":{"efforts":["high"]}}}}},
            "machines":{"cartae":{"enabled":true,"worker_id":"worker-cartae","provisioning_revision":1,
                "credential_fingerprint":"c".repeat(64),"allowed_agent_types":["native-test"],
                "mappings":{"quota-project":{"source_host":st.host.clone(),"source_root":root,
                    "remote_root":root.join("remote"),"expected_git_identity":"fixture172","mapping_revision":1}}}},
            "routing_policy":{"version":2,"revision":1,"enabled":true,
                "connections":[{"connection_id":"cartae-native","machine_id":"cartae",
                    "engine":"codex","agent_type":"native-test","enabled":true}],
                "model_catalog":{"cartae-native":[{"model":"custom/model","supported_efforts":["high"],
                    "default_effort":"high","provenance":"operator_observation"}]},
                "machine_policies":{"cartae":{"enabled":true}}}});
        st.registry =
            AgentRegistry::from_json(&value.to_string(), &root.join("quota172.json")).unwrap();
        let instance = task.child_instance.clone().unwrap();
        let response = handle_register_with_channel(
            "quota-child172",
            2,
            "native-test".into(),
            task.child.clone(),
            Some("cartae".into()),
            Some("codex_app_server".into()),
            ChannelReport::Known("unix".into()),
            Some(PresenceMode::Cli),
            None,
            Some("linux".into()),
            Some(instance.clone()),
            None,
            false,
            Some(true),
            &mut st,
            false,
        );
        assert!(
            matches!(response, DaemonToWrapper::Registered { .. }),
            "{response:?}"
        );
        st.managed_by_instance
            .insert(instance.clone(), task.task_id.clone());
        let digest = task.definition.digest.clone();
        task.remote_placement.as_mut().unwrap().definition_digest = digest.clone();
        for (case, allowed) in [
            ("current", true),
            ("definition", false),
            ("instance", false),
            ("machine", false),
            ("ambiguous", false),
            ("managed", false),
        ] {
            let mut declared = value.clone();
            if case == "ambiguous" {
                let mut other = declared["routing_policy"]["connections"][0].clone();
                other["connection_id"] = json!("other-account");
                declared["routing_policy"]["connections"]
                    .as_array_mut()
                    .unwrap()
                    .push(other);
                declared["routing_policy"]["model_catalog"]["other-account"] =
                    declared["routing_policy"]["model_catalog"]["cartae-native"].clone();
            }
            st.registry =
                AgentRegistry::from_json(&declared.to_string(), &root.join("quota172.json")).unwrap();
            st.managed_by_instance
                .insert(instance.clone(), task.task_id.clone());
            let mut candidate = task.clone();
            if case == "definition" {
                candidate
                    .remote_placement
                    .as_mut()
                    .unwrap()
                    .definition_digest = "f".repeat(64);
            }
            if case == "instance" {
                candidate.child_instance = Some("foreign-instance".into());
            }
            if case == "machine" {
                candidate.remote_placement.as_mut().unwrap().machine_id = "another-machine".into();
            }
            if case == "managed" {
                st.managed_by_instance.remove(&instance);
            }
            st.delegation_store.save(&candidate).unwrap();
            st.provider_limits = crate::provider_limits::ProviderLimits::default();
            assert!(matches!(
                handle_rate_limit(
                    &task.child,
                    "unknown".into(),
                    "rejected".into(),
                    None,
                    None,
                    None,
                    RateLimitSource::ClaudeStreamJson,
                    &mut st
                ),
                DaemonToWrapper::Ack { .. }
            ));
            let quota = st.provider_limits.routing_quota(
                "cartae-native",
                &digest,
                st.coordinator_epoch,
                &st.registry
                    .routing_connection_scope("cartae-native")
                    .unwrap(),
                &st.conn_instances.values().cloned().collect(),
                unix_timestamp(),
                30,
            );
            assert_eq!(quota.is_some_and(|q| q.launch_blocked), allowed, "{case}");
        }
        cleanup(&config);
    }

    #[test]
    fn remote162_resultat_canonique_notifie_parent_sans_recapture_legacy() {
        use bridget_transport::protocol::RemoteResultDisposition;
        let (mut st, config, task, result) = remote162_capture_fixture();
        st.pending_replies.push(PendingReply {
            msg_id: task.mission.clone(),
            from: task.owner.clone(),
            from_conn: "conn-1".into(),
            to: task.child.clone(),
            target_conn: "conn-1".into(),
            timeout_secs: 120,
            created_at: Instant::now() - Duration::from_secs(3600),
            frozen_secs: 0,
            escalation_level: 0,
            deferred_level: None,
        });
        assert_eq!(
            capture_remote_result(&mut st, &result.worker, &result),
            Ok(RemoteResultDisposition::Accepted {})
        );
        assert_eq!(
            st.store.get_request(&task.mission).unwrap().unwrap().state,
            "answered",
            "l'acceptation distante clôt le suivi sans attendre l'ACK transport"
        );
        let answered_task = st.delegation_store.get(&task.task_id).unwrap().unwrap();
        assert!(
            !answered_task.delivery_acked,
            "aucun ACK transport fabriqué"
        );
        st.store
            .connection()
            .execute(
                "UPDATE tracked_requests SET deadline_at=?1 WHERE id=?2",
                rusqlite::params![unix_timestamp() - 3600, task.mission],
            )
            .unwrap();
        assert!(
            collect_reminder_actions(&mut st, Instant::now() + Duration::from_secs(3600))
                .is_empty(),
            "une demande déjà répondue ne produit aucun rappel après son ancienne échéance"
        );
        let mut saved = st.delegation_store.get(&task.task_id).unwrap().unwrap();
        saved.state = "result_available".into();
        st.delegation_store.save(&saved).unwrap();
        let mut message =
            bridget_core::BridgetMessage::new(&saved.child, &saved.owner, &result.body);
        message.id = saved.result_message_id();
        message.in_reply_to = Some(saved.mission.clone());
        let mut controls = Vec::new();
        let reply = send_as_with_result_authority(
            &mut st,
            &saved.child,
            saved.child_instance.as_deref().unwrap(),
            &saved.task_id,
            message,
            saved.created_at,
            &mut controls,
            Some(&RetainedResultAuthority {
                task_id: saved.task_id.clone(),
            }),
        );
        assert!(
            matches!(
                reply,
                DaemonToWrapper::IdempotencyResult {
                    issue: IdempotencyIssue::Accepted { .. }
                        | IdempotencyIssue::OutcomeUnknown { .. },
                    ..
                }
            ),
            "{reply:?}"
        );
        assert_eq!(
            st.delegation_store
                .get(&task.task_id)
                .unwrap()
                .unwrap()
                .remote_result_receipts
                .len(),
            1
        );
        cleanup(&config);
    }

    #[test]
    fn remote170_ecriture_suivi_echoue_puis_reprise_entretien() {
        use bridget_transport::protocol::RemoteResultDisposition;
        let (mut st, config, task, result) = remote162_capture_fixture();
        st.store
            .connection()
            .execute_batch(
                "CREATE TRIGGER remote170_answer_fail BEFORE UPDATE OF state ON tracked_requests
                 WHEN NEW.state='answered'
                 BEGIN SELECT RAISE(ABORT, 'remote170 synthetic write failure'); END;",
            )
            .unwrap();
        assert_eq!(
            capture_remote_result(&mut st, &result.worker, &result),
            Ok(RemoteResultDisposition::Accepted {})
        );
        assert_eq!(
            st.store.get_request(&task.mission).unwrap().unwrap().state,
            "open",
            "l'échec SQL ne clôture pas fictivement le suivi"
        );
        st.pending_replies.push(PendingReply {
            msg_id: task.mission.clone(),
            from: task.owner.clone(),
            from_conn: "conn-1".into(),
            to: task.child.clone(),
            target_conn: "conn-1".into(),
            timeout_secs: 120,
            created_at: Instant::now() - Duration::from_secs(3600),
            frozen_secs: 0,
            escalation_level: 0,
            deferred_level: None,
        });
        assert!(
            collect_reminder_actions(&mut st, Instant::now() + Duration::from_secs(3600))
                .is_empty(),
            "un résultat accepté ne produit aucun rappel pendant la panne SQL"
        );
        st.store
            .connection()
            .execute_batch("DROP TRIGGER remote170_answer_fail;")
            .unwrap();
        let mut saved = st.delegation_store.get(&task.task_id).unwrap().unwrap();
        saved.state = "result_available".into();
        saved.result_sent = true;
        saved.cleanup_done = true;
        st.delegation_store.save(&saved).unwrap();
        let shared = Arc::new(Mutex::new(st));
        tick(&shared);
        let st = shared.lock().unwrap();
        assert_eq!(
            st.store.get_request(&task.mission).unwrap().unwrap().state,
            "answered",
            "le tick répare même une tâche déjà nettoyée sans rejouer le travail distant"
        );
        assert!(st.pending_replies.is_empty(), "aucun rappel ne reste armé");
        cleanup(&config);
    }

