    #[test]
    fn native150_purge_echec_recopie_suspend_purge_des_envois() {
        let (mut st, config, _rx, _reader) = fixture("n150-echec-recopie");
        let modele = tache_soldee_150(&mut st, "modele");
        let task = semer_terminale_150(&st, &modele, 1, "result_available");
        remise_native_150(&mut st, &task, "native-result-", true);
        let cle = IdempotencyKey::new(
            &crate::communication::issuer_scope(&task.task_id),
            OperationKind::Send,
            &format!("native-result-{}", task.task_id),
        )
        .unwrap();
        let loin = unix_timestamp() + 90 * JOUR_150;
        // Écriture impossible : la preuve d'accusé ne peut pas être enregistrée.
        let externe = rusqlite::Connection::open(&config.db_path).unwrap();
        externe.execute_batch("CREATE TRIGGER s150_bloque BEFORE UPDATE ON native_delegations BEGIN SELECT RAISE(ABORT,'bloque'); END;").unwrap();
        assert!(copy_delivery_acks(&st).is_err());
        super::super::maintain_stores(&mut st, loin);
        assert_eq!(
            st.idempotency.send_delivery_phase(&cle).unwrap().as_deref(),
            Some("acked"),
            "la remise survit au passage"
        );
        assert!(
            !st.delegation_store
                .get(&task.task_id)
                .unwrap()
                .unwrap()
                .delivery_acked
        );
        // L'écriture revient : la preuve est recopiée, puis seulement la remise est purgée.
        externe.execute_batch("DROP TRIGGER s150_bloque;").unwrap();
        super::super::maintain_stores(&mut st, loin);
        assert!(
            st.delegation_store
                .get(&task.task_id)
                .unwrap()
                .unwrap()
                .delivery_acked
        );
        assert_eq!(st.idempotency.send_delivery_phase(&cle).unwrap(), None);
        cleanup(&config);
    }

    #[test]
    fn native150_purge_arbre_volumineux_une_ecriture_de_flotte() {
        let (mut st, config, _rx, _reader) = fixture("n150-lot-flotte");
        let modele = tache_soldee_150(&mut st, "modele");
        let definition = st.registry.resolved_definition("native-test").unwrap();
        // Arbre : une racine et 4 enfants, chacun avec une entrée de flotte réellement présente.
        let mut ids = Vec::new();
        for i in 0..5 {
            let mut task = modele.clone();
            task.task_id = format!("lot150-{i}");
            task.child = Uuid::new_v4().to_string();
            task.mission = Uuid::new_v4().to_string();
            task.parent_task_id = (i > 0).then(|| "lot150-0".to_string());
            task.state = "cancelled".into();
            task.cleanup_done = true;
            task.completed_at = Some(unix_timestamp() + 120 * JOUR_150);
            st.delegation_store
                .insert(&task, &format!("req-lot150-{i}"), b"canon")
                .unwrap();
            let lease = match st
                .fleet
                .request_spawn(
                    &ordre_lancement_150(&task.child, &format!("saga-lot-{i}")),
                    unix_timestamp(),
                )
                .unwrap()
            {
                crate::fleet::SpawnSubmission::Start(lease) => lease,
                other => panic!("réservation inattendue: {other:?}"),
            };
            st.fleet
                .mark_starting(&lease, unix_timestamp(), &definition)
                .unwrap();
            st.fleet
                .register_connected(&lease, &lease.instance_id, unix_timestamp())
                .unwrap();
            st.fleet.mark_stopped(&task.child).unwrap();
            ids.push(task.child);
        }
        let avant = st.fleet.desired_write_count();
        assert_eq!(
            purge_retained(&st, unix_timestamp() + 200 * JOUR_150, None, usize::MAX),
            2,
            "modèle + arbre de test"
        );
        assert_eq!(
            st.fleet.desired_write_count() - avant,
            1,
            "une seule écriture de flotte pour tout l'arbre"
        );
        for child in &ids {
            assert_eq!(
                st.fleet
                    .desired_entry(child)
                    .unwrap()
                    .unwrap()
                    .lifecycle_state,
                DesiredLifecycleState::Decommissioned
            );
        }
        cleanup(&config);
    }

    #[test]
    fn native150_pause_refus_par_le_gestionnaire_complet_ne_fait_rien_avancer() {
        let (mut st, config, rx, _reader) = fixture("n150-gestionnaire");
        // Tâche préexistante en attente : seul un tick la ferait avancer.
        let attente = handle_locked("conn-1", request("attente"), &mut st).unwrap();
        pauser_150(&st, true);
        let shared = Arc::new(Mutex::new(st));
        let DaemonToWrapper::NativeDelegationResult { result } =
            handle("conn-1", request("refusee"), &shared)
        else {
            panic!("résultat attendu")
        };
        assert_eq!(result["code"], "referent_paused", "{result}");
        assert!(rx.try_recv().is_err(), "un refus ne lance aucun tick");
        let task = shared
            .lock()
            .unwrap()
            .delegation_store
            .get(attente["task_id"].as_str().unwrap())
            .unwrap()
            .unwrap();
        assert_eq!(task.state, "queued");
        // FR-008 : même un rejeu admis ne lance aucun travail pendant la pause.
        let DaemonToWrapper::NativeDelegationResult { result } =
            handle("conn-1", request("attente"), &shared)
        else {
            panic!("résultat attendu")
        };
        assert_eq!(result["status"], "queued");
        assert_eq!(result["suspended"], true);
        assert!(rx.try_recv().is_err(), "aucun lancement pendant la pause");
        pauser_150(&shared.lock().unwrap(), false);
        let DaemonToWrapper::NativeDelegationResult { result } =
            handle("conn-1", request("attente"), &shared)
        else {
            panic!("résultat attendu")
        };
        assert_eq!(result["task_id"], attente["task_id"]);
        assert_eq!(result["status"], "queued");
        assert_eq!(result["suspended"], false);
        assert!(matches!(
            rx.try_recv(),
            Ok(ManagedSupervisorCommand::Start { .. })
        ));
        drop(shared);
        cleanup(&config);
    }

    #[test]
    fn native150_entretien_purge_de_borne_sans_admission() {
        let (mut st, config, _rx, _reader) = fixture("n150-entretien-borne");
        let modele = modele_150(&mut st);
        // 5000 arbres soldés et récents : seule la pression de borne peut les purger.
        let recent = unix_timestamp() - 3600;
        semer_brut_150(
            &config,
            &modele,
            0,
            5000,
            "result_available",
            true,
            "instance-autre",
            recent - 6000,
        );
        let mut precedent = 5000;
        let mut passes = 0;
        loop {
            super::super::maintain_stores(&mut st, unix_timestamp());
            let restantes = st.delegation_store.tasks().unwrap().len();
            assert!(
                precedent - restantes <= crate::disk_hygiene::MAX_ENTRIES_PER_PASS,
                "au plus 128 arbres par passage"
            );
            if restantes == precedent {
                break;
            }
            precedent = restantes;
            passes += 1;
            assert!(passes <= 10, "la purge doit converger");
        }
        assert!(precedent < 4096, "total sous la borne : {precedent}");
        assert!(
            precedent >= 4096 - crate::disk_hygiene::MAX_ENTRIES_PER_PASS,
            "pas de purge au-delà du nécessaire : {precedent}"
        );
        assert!(passes >= 8, "plusieurs passages : {passes}");
        cleanup(&config);
    }

    #[test]
    fn native150_entretien_borne_et_age_cumulent_au_plus_128() {
        let (mut st, config, _rx, _reader) = fixture("n150-entretien-cumul");
        let modele = modele_150(&mut st);
        // 200 arbres soldés de plus de 7 jours (purge d'âge) et 4100 récents (pression de borne).
        let ancien = unix_timestamp() - 30 * JOUR_150;
        let recent = unix_timestamp() - 3600;
        semer_brut_150(
            &config,
            &modele,
            0,
            200,
            "result_available",
            true,
            "instance-autre",
            ancien,
        );
        semer_brut_150(
            &config,
            &modele,
            200,
            4100,
            "result_available",
            true,
            "instance-autre",
            recent - 6000,
        );
        assert_eq!(st.delegation_store.tasks().unwrap().len(), 4300);
        super::super::maintain_stores(&mut st, unix_timestamp());
        let restantes = st.delegation_store.tasks().unwrap().len();
        assert!(
            4300 - restantes <= crate::disk_hygiene::MAX_ENTRIES_PER_PASS,
            "au plus 128 arbres par passage, âge et borne cumulés : {restantes}"
        );
        assert_eq!(
            restantes,
            4300 - crate::disk_hygiene::MAX_ENTRIES_PER_PASS,
            "le quota du passage est consommé"
        );
        cleanup(&config);
    }

    #[test]
    fn native150_delai_suivi_realigne_apres_echec_d_ecriture() {
        // Ancien suivi150 divergent : la date d'émission152 ne nécessite plus
        // d'alignement au premier envoi. Conserver le cas réel d'UPDATE en échec.
        let (shared, config, task_id, deadline, message) =
            parent_en_cours_150(request_delai_150("parent", Some(120)), 30);
        {
            let st = shared.lock().unwrap();
            let task = st.delegation_store.get(&task_id).unwrap().unwrap();
            st.store
                .set_request_deadline(&message.id, task.created_at + 120)
                .unwrap();
        }
        rusqlite::Connection::open(&config.db_path).unwrap()
            .execute_batch("CREATE TRIGGER s150_suivi_bloque BEFORE UPDATE OF deadline_at ON tracked_requests BEGIN SELECT RAISE(ABORT,'bloque'); END;")
            .unwrap();
        assert!(
            shared
                .lock()
                .unwrap()
                .store
                .set_request_deadline(&message.id, deadline)
                .is_err(),
            "vrai échec UPDATE"
        );
        let suivi_deadline = |shared: &Arc<Mutex<DaemonState>>| {
            shared
                .lock()
                .unwrap()
                .store
                .get_request(&message.id)
                .unwrap()
                .expect("demande suivie")
                .deadline_at
        };
        assert_ne!(suivi_deadline(&shared), deadline, "ancien suivi divergent");
        // Tant que l'écriture échoue, le tick réessaie sans casser la tâche.
        tick(&shared);
        assert_ne!(suivi_deadline(&shared), deadline);
        assert_eq!(
            shared
                .lock()
                .unwrap()
                .delegation_store
                .get(&task_id)
                .unwrap()
                .unwrap()
                .state,
            "working"
        );
        // L'écriture revient : le tick suivant réaligne le suivi sur mission_deadline_at.
        rusqlite::Connection::open(&config.db_path)
            .unwrap()
            .execute_batch("DROP TRIGGER s150_suivi_bloque;")
            .unwrap();
        tick(&shared);
        assert_eq!(suivi_deadline(&shared), deadline, "suivi réaligné");
        drop(shared);
        cleanup(&config);
    }

    #[test]
    fn native150_delai_suivi_aligne_sur_admission_apres_lancement_retarde() {
        // Délai explicite, lancement retardé de 30 s : le suivi durable suit l'admission de la mission.
        let (shared, config, task_id, deadline, message) =
            parent_en_cours_150(request_delai_150("parent", Some(120)), 30);
        {
            let st = shared.lock().unwrap();
            let task = st.delegation_store.get(&task_id).unwrap().unwrap();
            let suivi = st
                .store
                .get_request(&message.id)
                .unwrap()
                .expect("demande suivie");
            assert_eq!(
                suivi.deadline_at, deadline,
                "suivi aligné sur mission_deadline_at"
            );
            assert_eq!(suivi.created_at, task.mission_issued_at.unwrap());
            assert_eq!(suivi.deadline_at, task.mission_issued_at.unwrap() + 120);
            assert_eq!(message.id, task.mission);
            assert!(
                deadline - task.created_at >= 150,
                "l'échéance compte depuis l'admission, pas la création"
            );
        }
        // L'enveloppe de l'envoi de mission n'a pas changé : le délai reste celui du parent.
        assert_eq!(message.reply_timeout, Some(120));
        drop(shared);
        cleanup(&config);
        // FR-010 : le défaut3600 part aussi de la première émission de mission.
        let (shared, config, task_id, deadline, message) =
            parent_en_cours_150(request_delai_150("parent", None), 30);
        {
            let st = shared.lock().unwrap();
            let task = st.delegation_store.get(&task_id).unwrap().unwrap();
            let suivi = st
                .store
                .get_request(&message.id)
                .unwrap()
                .expect("demande suivie");
            assert_eq!(suivi.created_at, task.mission_issued_at.unwrap());
            assert_eq!(suivi.deadline_at, task.mission_issued_at.unwrap() + 3600);
            assert_eq!(suivi.deadline_at, deadline);
            assert!(deadline - task.created_at >= 3630);
            assert_eq!(message.id, task.mission);
        }
        assert_eq!(message.reply_timeout, Some(3600));
        drop(shared);
        cleanup(&config);
    }

    // T014 : fonction de production, origine d'émission152 explicite.
    #[test]
    fn native160_attente_qualification_table() {
        let (state, config, original, _parent, _child) = native160_mission(true);
        let now = unix_timestamp();
        let NativeDelegationRequest::Delegate { agent_type, .. } = &original.request else {
            panic!("Delegate")
        };
        for case in [
            "six_hours",
            "too_far",
            "past_hold",
            "two_done",
            "before_mission",
            "before_last_wait",
            "codex_global",
            "credits_available",
            "different_instance",
        ] {
            let mut task = original.clone();
            task.reply_timeout = Some(120);
            task.mission_issued_at = Some(now - 100);
            task.mission_deadline_at = Some(now + 20); // origine = deadline - reply_timeout
            let reset = if case == "too_far" {
                now + 21601
            } else if case == "past_hold" {
                now - 1
            } else {
                now + 21600
            };
            let observed = if case == "before_mission" {
                now - 101
            } else if case == "before_last_wait" {
                now - 30
            } else {
                now - 2
            };
            if case == "past_hold" {
                task.quota_hold = Some(crate::delegation::QuotaHold {
                    since: now - 4,
                    error: "hold160".into(),
                    execution_id: format!("execution-{}", task.mission),
                });
            }
            if matches!(case, "two_done" | "before_last_wait") {
                let count = if case == "two_done" { 2 } else { 1 };
                for round in 1..=count {
                    task.quota_waits.push(
                        serde_json::from_value(native160_wait(
                            &task,
                            now - 80,
                            now - 60,
                            round,
                            "done",
                            Some(now - 20),
                            Some("done-pure160"),
                        ))
                        .unwrap(),
                    );
                }
            }
            let mut limits = crate::provider_limits::ProviderLimits::default();
            limits.record_scoped(
                agent_type,
                if case == "different_instance" {
                    "other-instance"
                } else {
                    task.child_instance.as_deref().unwrap()
                },
                bridget_transport::protocol::RateLimitFact {
                    credits: (case == "credits_available").then_some(
                        bridget_transport::protocol::CodexCredits {
                            has_credits: Some(true),
                            unlimited: Some(false),
                            spend_control_reached: false,
                        },
                    ),
                    window: "five_hour".into(),
                    status: "rate_limit_reached".into(),
                    resets_at: Some(reset),
                    used_percent: if case == "codex_global" {
                        None
                    } else {
                        Some(100)
                    },
                },
                bridget_transport::protocol::RateLimitSource::CodexAppServer,
                observed,
            );
            let expected = match case {
                "six_hours" => Qualification::Wait { reset_at: reset },
                "too_far" => Qualification::TooFar { reset_at: reset },
                "past_hold" => Qualification::Past { reset_at: reset },
                "two_done" => Qualification::RoundsDone { reset_at: reset },
                _ => Qualification::NoFact,
            };
            assert_eq!(qualify_quota(&task, now, &limits), expected, "{case}");
            // Le véritable recheck distant utilise le compte de l'enfant,
            // même si un autre compte du même profil a publié une fenêtre100.
            let mut probe = task.clone();
            probe.permission_snapshot = None;
            probe.remote_placement = None;
            let mut st = state.lock().unwrap();
            st.provider_limits = limits;
            let blocked = !matches!(
                case,
                "past_hold" | "codex_global" | "credits_available" | "different_instance"
            );
            assert_eq!(
                recheck_remote_dispatch(&st, &probe, &probe)
                    .err()
                    .as_deref(),
                Some(if blocked {
                    "provider_quota_exhausted"
                } else {
                    "remote_placement_missing"
                }),
                "{case}"
            );
        }
        drop(state);
        cleanup(&config);
    }

    // T017 : vue publique additive ; Lineage inchangé pour les seuls faitsquota.
    #[test]
    fn native160_vue_quota_wait_additive_et_lineage_identique() {
        let (state, config, original, _parent, _child) = native160_mission(true);
        let now = unix_timestamp();
        let st = state.lock().unwrap();
        let baseline = serde_json::to_vec(
            &st.delegation_store
                .lineage_page(OWNER, 100, None, |_| false)
                .unwrap(),
        )
        .unwrap();
        assert!(current_task_view(&st, &original, true).unwrap()["quota_wait"].is_null());
        for phase in ["hold", "waiting", "relaunching", "done"] {
            let mut task = original.clone();
            if phase == "hold" {
                task.quota_hold = Some(crate::delegation::QuotaHold {
                    since: now,
                    error: "hold160".into(),
                    execution_id: format!("execution-{}", task.mission),
                });
            } else {
                task.quota_waits.push(
                    serde_json::from_value(native160_wait(
                        &task,
                        now,
                        now + 1800,
                        1,
                        phase,
                        if phase == "done" { Some(now) } else { None },
                        None,
                    ))
                    .unwrap(),
                );
            }
            st.delegation_store.save(&task).unwrap();
            let value = current_task_view(&st, &task, true).unwrap();
            assert_eq!(value["status"], "working");
            if matches!(phase, "waiting" | "relaunching") {
                assert_eq!(
                    value["quota_wait"],
                    json!({"round":1,"phase":phase,"resumes_at":now+1830})
                );
            } else {
                assert!(value["quota_wait"].is_null());
            }
            assert_eq!(
                serde_json::to_vec(
                    &st.delegation_store
                        .lineage_page(OWNER, 100, None, |_| false)
                        .unwrap()
                )
                .unwrap(),
                baseline,
                "{phase}: aucun signalLineage des faitsquota"
            );
            assert!(
                st.delegation_store
                    .failed_for_owner(OWNER)
                    .unwrap()
                    .is_empty()
            );
            assert!(st.pending_replies.iter().any(|p| p.msg_id == task.mission));
        }
        cleanup(&config);
    }

    // T016/T021 : le fait volatile connu ne sauve pas un hold après restart.
    #[test]
    fn native160_attente_redemarrage_pendant_hold() {
        let (state, config, mut task, mut parent, _child) = native160_mission(true);
        let now = unix_timestamp();
        task.quota_hold = Some(crate::delegation::QuotaHold {
            since: now,
            error: "erreur originale duhold160".into(),
            execution_id: format!("execution-{}", task.mission),
        });
        native160_quota(&state, &task, now + 1800);
        {
            let mut st = state.lock().unwrap();
            st.delegation_store.save(&task).unwrap();
            reouvrir_flotte_152(&mut st, &config);
            st.provider_limits = crate::provider_limits::ProviderLimits::default();
            prepare_restart(&mut st).unwrap();
            let saved = st.delegation_store.get(&task.task_id).unwrap().unwrap();
            assert_eq!(saved.state, "failed");
            assert_eq!(saved.error.as_deref(), Some("erreur originale duhold160"));
            assert!(saved.quota_hold.is_none());
            assert!(saved.quota_waits.is_empty());
            assert_eq!(saved.restart_resumes, task.restart_resumes);
        }
        tick(&state);
        let mut raw = String::new();
        parent.read_line(&mut raw).unwrap();
        let frame: Value = serde_json::from_str(raw.trim()).unwrap();
        assert_eq!(
            frame["message"]["id"],
            format!("native-failure-{}", task.task_id)
        );
        raw.clear();
        assert!(
            parent.read_line(&mut raw).is_err(),
            "un seul avis durable, aucun direct"
        );
        cleanup(&config);
    }

    // T015 : les refus sur terminal ferment le cheminA sans créer un autre avis.
    #[test]
    fn native160_attente_un_seul_avis_terminal_preserve() {
        for terminal in ["failed", "cancelled", "result_available"] {
            let (state, config, mut task, mut parent, _child) = native160_mission(true);
            task.state = terminal.into();
            task.error = if terminal == "failed" {
                Some("premier échec160".into())
            } else {
                None
            };
            task.failure_sent = terminal == "failed";
            {
                let st = state.lock().unwrap();
                st.delegation_store.save(&task).unwrap();
            }
            let rejection:WrapperToDaemon=serde_json::from_value(json!({"type":"DeliveryRejected","id":task.mission,"reason":"refus tardif160","execution_id":format!("execution-{}",task.mission),"generation":1})).unwrap();
            assert!(handle_wrapper_message("child-conn", rejection, &state).is_none());
            let st = state.lock().unwrap();
            let saved = st.delegation_store.get(&task.task_id).unwrap().unwrap();
            assert_eq!(saved.state, task.state);
            assert_eq!(saved.error, task.error);
            assert_eq!(saved.failure_sent, task.failure_sent);
            let mut raw = String::new();
            let _ = parent.read_line(&mut raw);
            assert!(
                raw.is_empty(),
                "{terminal}: zéro nouvel avis direct/durable"
            );
            cleanup(&config);
        }
    }

    // T015/T016 : B a déjà créé l'attente ; A ne doit ni la remplacer ni notifier.
    #[test]
    fn native160_attente_chemin_a_apres_b_sans_effet() {
        let (state, config, task, mut parent, _child) = native160_mission(true);
        native160_quota(&state, &task, unix_timestamp() + 1800);
        transition_wrapper_152(&state, &task, "failed");
        tick(&state);
        let before = state
            .lock()
            .unwrap()
            .delegation_store
            .get(&task.task_id)
            .unwrap()
            .unwrap();
        assert_eq!(before.quota_waits.len(), 1);
        let rejection:WrapperToDaemon=serde_json::from_value(json!({"type":"DeliveryRejected","id":task.mission,"reason":"AaprèsB160","execution_id":format!("execution-{}",task.mission),"generation":1})).unwrap();
        handle_wrapper_message("child-conn", rejection, &state);
        let st = state.lock().unwrap();
        let after = st.delegation_store.get(&task.task_id).unwrap().unwrap();
        assert_eq!(after.quota_waits, before.quota_waits);
        assert_eq!(after.quota_hold, before.quota_hold);
        assert_eq!(after.state, "working");
        assert!(st.pending_replies.iter().any(|p| p.msg_id == task.mission));
        assert!(
            st.delegation_store
                .failed_for_owner(OWNER)
                .unwrap()
                .is_empty()
        );
        let mut raw = String::new();
        let _ = parent.read_line(&mut raw);
        assert!(raw.is_empty());
        cleanup(&config);
    }

    // T023 : union partielle, même gel suivi/délai, puis borne sans parent/enfant.
    #[test]
    fn native160_gel_chevauchement_suivi_rappels_et_borne() {
        let (state, config, mut task, _parent, _child) = native160_mission(true);
        let now = unix_timestamp();
        task.reply_timeout = Some(3600);
        task.mission_deadline_at = Some(now + 1800);
        task.quota_waits.push(
            serde_json::from_value(native160_wait(
                &task,
                now - 1800,
                now + 1800,
                1,
                "waiting",
                None,
                None,
            ))
            .unwrap(),
        );
        let mut st = state.lock().unwrap();
        st.delegation_store.save(&task).unwrap();
        st.store
            .connection()
            .execute(
                "UPDATE tracked_requests SET created_at=?1 WHERE id=?2",
                rusqlite::params![now - 1800, task.mission],
            )
            .unwrap();
        control_pause_a_152(&st, true, now - 2100);
        control_pause_a_152(&st, false, now - 1500);
        // Origine152=now-1800 : pause chevauchante est rognée ; quota couvre déjà1800.
        assert_eq!(
            effective_deadline(&st, &task, now).unwrap(),
            Some(now + 3600)
        );
        assert_eq!(
            request_frozen_secs(&st, &task.mission, now).unwrap(),
            Some(1800)
        );
        for pending in &mut st.pending_replies {
            if pending.msg_id == task.mission {
                pending.created_at = Instant::now() - Duration::from_secs(1800);
            }
        }
        let actions = collect_reminder_actions(&mut st, Instant::now());
        assert!(actions.is_empty(), "aucun palier pendant quotaouvert");
        let before = effective_deadline(&st, &task, now + 1830).unwrap();
        st.router.unregister_by_conn("child-conn");
        st.connections.remove("child-conn");
        assert_eq!(
            effective_deadline(&st, &task, now + 1831).unwrap(),
            before,
            "gelquota cesse à reset+30 quellequeconnexion"
        );
        assert_eq!(
            request_frozen_secs(&st, &task.mission, now + 1831).unwrap(),
            request_frozen_secs(&st, &task.mission, now + 1830).unwrap()
        );
        cleanup(&config);
    }

    // T024 : pause retarde l'admissionwaiting ; levée laisse la même identité.
    #[test]
    fn native160_gel_pause_differe_puis_relance() {
        let (state, config, task, _parent, mut child) = native160_mission(true);
        transition_wrapper_152(&state, &task, "failed");
        native160_stage(&state, &config, &task, "b");
        {
            let st = state.lock().unwrap();
            control_pause_a_152(&st, true, unix_timestamp());
        }
        tick(&state);
        let paused = state
            .lock()
            .unwrap()
            .delegation_store
            .get(&task.task_id)
            .unwrap()
            .unwrap();
        assert_eq!(
            paused.quota_waits[0].phase,
            crate::delegation::QuotaWaitPhase::Waiting
        );
        let mut raw = String::new();
        assert!(child.read_line(&mut raw).is_err());
        {
            let st = state.lock().unwrap();
            control_pause_a_152(&st, false, unix_timestamp());
        }
        tick(&state);
        let saved = state
            .lock()
            .unwrap()
            .delegation_store
            .get(&task.task_id)
            .unwrap()
            .unwrap();
        assert_eq!(saved.mission, task.mission);
        assert_eq!(
            saved.quota_waits[0].identity,
            paused.quota_waits[0].identity
        );
        assert_eq!(
            saved.quota_waits[0].phase,
            crate::delegation::QuotaWaitPhase::Relaunching
        );
        raw.clear();
        child.read_line(&mut raw).unwrap();
        let frame: Value = serde_json::from_str(raw.trim()).unwrap();
        assert_eq!(frame["message"]["id"], task.mission);
        cleanup(&config);
    }

    // T020 : relance du message initial, ACK puis résultat unique vers le parent.
    #[test]
    fn native160_relance_meme_identifiant_et_resultat_rendu_une_fois() {
        // Absorption de l'ancienrésultat : aucune mutationpendant Hold/WaitsansACKquota.
        for phase in ["hold", "waiting"] {
            let (state, config, mut task, _parent, _child) = native160_mission(true);
            transition_wrapper_152(&state, &task, "failed");
            if phase == "hold" {
                task.quota_hold = Some(crate::delegation::QuotaHold {
                    since: unix_timestamp(),
                    error: "holdorigine160".into(),
                    execution_id: format!("execution-{}", task.mission),
                });
                state.lock().unwrap().delegation_store.save(&task).unwrap();
            } else {
                native160_stage(&state, &config, &task, "b");
            }
            let mut st = state.lock().unwrap();
            let before =
                serde_json::to_vec(&st.delegation_store.get(&task.task_id).unwrap().unwrap())
                    .unwrap();
            let mut old_reply =
                bridget_core::BridgetMessage::new(&task.child, &task.owner, "ancienrésultat160");
            old_reply.in_reply_to = Some(task.mission.clone());
            assert!(
                capture_reply(&mut st, "child-conn", &old_reply).unwrap(),
                "absorbé pour ACKtransportseulement"
            );
            assert_eq!(
                serde_json::to_vec(&st.delegation_store.get(&task.task_id).unwrap().unwrap())
                    .unwrap(),
                before,
                "{phase}: aucunrésultat ni soldequota ajouté"
            );
            cleanup(&config);
        }
        let (state, config, task, mut parent, mut child) = native160_mission(true);
        let request_before = serde_json::to_vec(&task.request).unwrap();
        transition_wrapper_152(&state, &task, "failed");
        native160_stage(&state, &config, &task, "b");
        tick(&state);
        let mut raw = String::new();
        child.read_line(&mut raw).unwrap();
        let DaemonToWrapper::DeliverIdempotent {
            message,
            delivery_id,
            delivery_generation,
            ..
        } = decode(raw.trim()).unwrap()
        else {
            panic!("remise réellequota")
        };
        assert_eq!(message.id, task.mission);
        assert!(
            handle_wrapper_message(
                "child-conn",
                WrapperToDaemon::DeliverAcked {
                    delivery_id,
                    delivery_generation
                },
                &state
            )
            .is_none()
        );
        // Frontière g : remiseACKed ; TaskWait n'a pas encore été soldée par tick.
        let saved = state
            .lock()
            .unwrap()
            .delegation_store
            .get(&task.task_id)
            .unwrap()
            .unwrap();
        assert_eq!(
            saved.quota_waits[0].phase,
            crate::delegation::QuotaWaitPhase::Relaunching
        );
        assert_eq!(saved.mission, task.mission);
        assert_eq!(serde_json::to_vec(&saved.request).unwrap(), request_before);
        transition_wrapper_152(&state, &task, "running");
        transition_wrapper_152(&state, &task, "completed");
        let stop = {
            let mut st = state.lock().unwrap();
            let mut result =
                bridget_core::BridgetMessage::new(&task.child, &task.owner, "résultatquota160");
            result.in_reply_to = Some(task.mission.clone());
            assert!(capture_reply(&mut st, "child-conn", &result).unwrap());
            let captured = st.delegation_store.get(&task.task_id).unwrap().unwrap();
            assert_eq!(
                captured.quota_waits[0].phase,
                crate::delegation::QuotaWaitPhase::Done,
                "ACK→reply avanttick solde mêmeACK durable"
            );
            assert_eq!(
                captured.state, "waiting_for_children",
                "capture durable avant publication du tick"
            );
            assert_eq!(captured.result.as_deref(), Some("résultatquota160"));
            st.managed_spawns.values().next().unwrap().stop.clone()
        };
        let (done, observer) = observer_arrets_152(vec![stop]);
        tick(&state);
        tick(&state);
        done.send(()).unwrap();
        observer.join().unwrap();
        raw.clear();
        parent.read_line(&mut raw).unwrap();
        let DaemonToWrapper::DeliverIdempotent { message, .. } = decode(raw.trim()).unwrap() else {
            panic!("résultat réelquota")
        };
        assert_eq!(message.id, format!("native-result-{}", task.task_id));
        assert_eq!(message.body, "résultatquota160");
        raw.clear();
        assert!(
            parent.read_line(&mut raw).is_err(),
            "aucun doublon résultat après deux ticks"
        );
        let st = state.lock().unwrap();
        assert_eq!(
            st.delegation_store
                .get(&task.task_id)
                .unwrap()
                .unwrap()
                .quota_waits
                .len(),
            1
        );
        let leaf = st
            .execution_store
            .latest_in_chain(&format!("execution-{}", task.mission))
            .unwrap()
            .unwrap();
        assert_eq!(leaf.generation, 2);
        cleanup(&config);
    }

    // T024 : annulation réelle et backend de stop152 ; aucune émission après annulation.
    #[test]
    fn native160_gel_annulation_attente_relaunch_et_hold() {
        for phase in ["hold", "b", "c", "d", "dispatching"] {
            let (state, config, task, _parent, mut child) = native160_mission(true);
            transition_wrapper_152(&state, &task, "failed");
            if phase == "hold" {
                let rejection:WrapperToDaemon=serde_json::from_value(json!({"type":"DeliveryRejected","id":task.mission,"reason":"holdàannuler160","execution_id":format!("execution-{}",task.mission),"generation":1})).unwrap();
                handle_wrapper_message("child-conn", rejection, &state);
                assert!(
                    state
                        .lock()
                        .unwrap()
                        .delegation_store
                        .get(&task.task_id)
                        .unwrap()
                        .unwrap()
                        .quota_hold
                        .is_some()
                );
            } else {
                let resumed = native160_stage(
                    &state,
                    &config,
                    &task,
                    if phase == "dispatching" { "e" } else { phase },
                );
                if phase == "dispatching" {
                    let mut st = state.lock().unwrap();
                    let message = st
                        .execution_store
                        .execution_message(&resumed)
                        .unwrap()
                        .unwrap();
                    let continuation = st
                        .execution_store
                        .continuation_for(&resumed)
                        .unwrap()
                        .unwrap();
                    let scope = st.idempotency.supervisor_scope().unwrap();
                    let key = IdempotencyKey::new(
                        scope,
                        OperationKind::Send,
                        format!("recovery-{resumed}"),
                    )
                    .unwrap();
                    let canonical = canonical_send(
                        &key.issuer_scope,
                        &key.idempotency_key,
                        &message,
                        continuation.observed_at,
                    );
                    let Reservation::Replayed { .. } = st
                        .idempotency
                        .reserve(
                            &key,
                            &canonical,
                            continuation.observed_at,
                            CLIENT_IDEMPOTENCY_HORIZON_SECS,
                            unix_timestamp(),
                            CLIENT_ISSUED_AT_TOLERANCE_SECS,
                        )
                        .unwrap()
                    else {
                        panic!("réservation e réelle")
                    };
                    let delivery = crate::idempotency::SendDelivery {
                        delivery_id: format!("cancel-quota-{resumed}"),
                        recipient_instance_id: task.child_instance.clone().unwrap(),
                        delivery_generation: 902,
                        expires_at: unix_timestamp() + 3600,
                        message_bytes: serde_json::to_vec(&message).unwrap(),
                    };
                    let link = crate::idempotency::DeliveryExecutionLink {
                        delivery_id: delivery.delivery_id.clone(),
                        submission_id: message.id,
                        execution_id: resumed,
                    };
                    st.idempotency
                        .begin_send_delivery_with_execution(&key, &delivery, None, &link)
                        .unwrap();
                    assert_eq!(
                        st.idempotency.send_delivery_phase(&key).unwrap().as_deref(),
                        Some("dispatching")
                    );
                }
            }
            let stop = {
                let mut st = state.lock().unwrap();
                handle_locked(
                    "conn-1",
                    NativeDelegationRequest::Cancel {
                        task_id: task.task_id.clone(),
                    },
                    &mut st,
                )
                .unwrap();
                st.managed_spawns.values().next().unwrap().stop.clone()
            };
            let (done, observer) = observer_arrets_152(vec![stop]);
            tick(&state);
            tick(&state);
            done.send(()).unwrap();
            assert_eq!(observer.join().unwrap(), vec![true]);
            let mut st = state.lock().unwrap();
            let saved = st.delegation_store.get(&task.task_id).unwrap().unwrap();
            assert_eq!(saved.state, "cancelled", "{phase}");
            assert!(saved.quota_hold.is_none());
            if phase != "hold" {
                assert_eq!(
                    saved.quota_waits[0].phase,
                    crate::delegation::QuotaWaitPhase::Done
                );
                assert!(saved.quota_waits[0].until.is_some());
            }
            let leaf = st
                .execution_store
                .latest_in_chain(&format!("execution-{}", task.mission))
                .unwrap()
                .unwrap();
            assert!(
                matches!(leaf.state.as_str(), "failed" | "unreachable"),
                "{phase}: feuilleclôturée avant le solde"
            );
            if phase == "dispatching" {
                let key = IdempotencyKey::new(
                    st.idempotency.supervisor_scope().unwrap(),
                    OperationKind::Send,
                    format!("recovery-{}", leaf.execution_id),
                )
                .unwrap();
                assert_eq!(
                    st.idempotency.send_delivery_phase(&key).unwrap().as_deref(),
                    Some("indeterminate")
                );
            }
            assert!(
                !may_resume(
                    &st,
                    &saved,
                    &leaf.execution_id,
                    task.child_instance.as_ref().unwrap()
                )
                .unwrap()
            );
            drop(st);
            let mut frames = Vec::new();
            loop {
                let mut raw = String::new();
                match child.read_line(&mut raw) {
                    Ok(0) => break,
                    Err(error)
                        if matches!(
                            error.kind(),
                            std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                        ) =>
                    {
                        break;
                    }
                    Err(error) => panic!("lecture contrôle {phase}: {error}"),
                    Ok(_) => {
                        let frame: Value = serde_json::from_str(raw.trim()).unwrap();
                        let mission_id = frame
                            .get("message")
                            .and_then(|m| m.get("id"))
                            .or_else(|| frame.get("id"));
                        let kind = frame["type"].as_str().unwrap_or("?");
                        let metadata = json!({"type":kind,"id":mission_id,
                            "execution_id":frame.get("execution_id"),
                            "command_id":frame.get("command_id")});
                        assert!(
                            !(matches!(kind, "DeliverExecution" | "DeliverIdempotent" | "Deliver")
                                && mission_id == Some(&json!(task.mission))),
                            "{phase}: mission annulée remise, metadata={metadata}"
                        );
                        frames.push(metadata);
                    }
                }
            }
            eprintln!("T024 contrôle légitime après annulation {phase}: {frames:?}");
            cleanup(&config);
        }
    }

